    def allowed(version, constraints):
        return all((low is None or version >= low) and
                   (high is None or version <= high)
                   for low, high in constraints)

    def search(required, assigned):
        nonlocal best, best_vector
        for name, version in assigned.items():
            if not allowed(version, required[name]):
                return

        pending = [name for name in required if name not in assigned]
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = assigned.copy()
                best_vector = vector
            return

        name = min(pending)
        rows = sorted(packages[name], key=lambda row: row['version'], reverse=True)
        for row in rows:
            version = row['version']
            if not allowed(version, required[name]):
                continue
            next_required = {key: value.copy() for key, value in required.items()}
            next_assigned = assigned.copy()
            next_assigned[name] = version
            valid = True
            for dep_name, dep_bounds in dependencies(row.get('deps', [])):
                if dep_name not in packages:
                    valid = False
                    break
                next_required.setdefault(dep_name, []).append(dep_bounds)
                if dep_name in next_assigned and not allowed(
                        next_assigned[dep_name], next_required[dep_name]):
                    valid = False
                    break
            if valid:
                search(next_required, next_assigned)

    search(initial, {})
    return {'versions': best or {}}
